CREATE OR REPLACE FUNCTION avg_onboarding_days(department_name TEXT)
RETURNS NUMERIC AS $$
BEGIN
  RETURN (
    SELECT COALESCE(ROUND(AVG(os.completion_date - e.hire_date), 2), 0.00)
    FROM employees e
    JOIN onboarding_sessions os ON e.employee_id = os.employee_id
    WHERE e.department = department_name
      AND os.completion_date IS NOT NULL
  );
END;
$$ LANGUAGE plpgsql;

SELECT avg_onboarding_days('Engineering') AS result;
